// Host Application (Shell) - dynamically loading Remotes
import('navApp/Header');
import('cartApp/MiniCart');

# Nginx Reverse Proxy
location /store/ {
    proxy_pass http://store-service.internal;
}
location /checkout/ {
    proxy_pass http://checkout-service.internal;
}

// webpack.config.js (Remote)
new ModuleFederationPlugin({
  name: 'cart',
  filename: 'remoteEntry.js',
  exposes: {
    './MiniCart': './src/components/MiniCart',
  },
  shared: { react: { singleton: true }, 'react-dom': { singleton: true } },
});

// root-config.js
registerApplication({
  name: '@org/navbar',
  app: () => System.import('@org/navbar'),
  activeWhen: ['/'],
});
registerApplication({
  name: '@org/billing',
  app: () => System.import('@org/billing'),
  activeWhen: ['/billing'],
});
start();

// Phát sự kiện từ Product App:
window.dispatchEvent(new CustomEvent('cart:item-added', { detail: { productId: 101, qty: 1 } }));

// Lắng nghe ở Cart App:
window.addEventListener('cart:item-added', (e: any) => {
  updateBadge(e.detail);
});

// Remote Component
export function RemoteApp({ initialPath, onNavigate }: Props) {
  const router = createMemoryRouter(routes, { initialEntries: [initialPath] });
  // Lắng nghe thay đổi để báo cho Host
  useEffect(() => router.subscribe(state => onNavigate(state.location.pathname)), [router]);
  return <RouterProvider router={router} />;
}

// tailwind.config.js cho Remote Cart
module.exports = {
  prefix: 'cart-',
  important: '#cart-root',
};

class CartElement extends HTMLElement {
  connectedCallback() {
    const root = ReactDOM.createRoot(this.attachShadow({ mode: 'open' }));
    root.render(<CartWidget />);
  }
}
customElements.define('mfe-cart', CartElement);

// Component test với Mock Shell Container
describe('RemoteCart', () => {
  it('dispatches checkout event', () => {
    const spy = vi.fn();
    window.addEventListener('cart:checkout', spy);
    render(<RemoteCart />);
    fireEvent.click(screen.getByText('Checkout'));
    expect(spy).toHaveBeenCalled();
  });
});

// Đánh đổi rõ rệt:
// Monolith: 1 bundle 2MB, tải 1 lần
// Micro-frontend: 1 Shell 500KB + 4 Remotes 400KB mỗi cái = 2.1MB + overhead network latency.

// qiankun start
import { registerMicroApps, start } from 'qiankun';
registerMicroApps([
  { name: 'react app', entry: '//localhost:7100', container: '#container', activeRule: '/react' },
]);
start();

// webpack.config.js
new ModuleFederationPlugin({
  shared: {
    react: {
      singleton: true,
      requiredVersion: deps.react,
      eager: false, // Để lazy load tránh lock Host startup
    },
    'react-dom': {
      singleton: true,
      requiredVersion: deps['react-dom'],
    },
  },
});

// Shared auth package hoặc Host expose:
export const authService = {
  getUser: () => ({ ...currentUser }), // trả về shallow copy
  subscribe: (cb: (user: User) => void) => eventEmitter.on('user_change', cb),
  // Chỉ Host mới gọi được login/logout
};

// Next.js Multi-Zones config (next.config.js)
async rewrites() {
  return [
    { source: '/blog/:path*', destination: 'https://blog.my-domain.com/blog/:path*' },
  ];
}

export function SafeRemoteLoader({ children, fallback }: Props) {
  return (
    <ErrorBoundary fallback={fallback ?? <DefaultErrorAlert />}>
      <Suspense fallback={<WidgetSkeleton />}>
        {children}
      </Suspense>
    </ErrorBoundary>
  );
}
